// The hero's source art: a cut-out armet painting (public/images/armet.png,
// generated by scripts/make-armet.mjs). The ASCII renderer samples this
// every frame; the moving sheen below is what makes the steel glint.

export const ART_W = 420;
export const ART_H = 540;
export const ARMET_SRC = "/images/armet.png";

export function drawArmet(g: CanvasRenderingContext2D, img: HTMLImageElement, t: number) {
  g.globalCompositeOperation = "source-over";
  g.fillStyle = "#000";
  g.fillRect(0, 0, ART_W, ART_H);

  // Slow "torchlight" breathing.
  const breathe = 0.94 + Math.sin(t * 1.1) * 0.04;
  g.globalAlpha = breathe;
  g.drawImage(img, 0, 0, ART_W, ART_H);
  g.globalAlpha = 1;

  // A diagonal sheen that sweeps across the steel every few seconds.
  const cycle = (t * 0.22) % 1.6;
  if (cycle < 1) {
    const x = -180 + cycle * (ART_W + 360);
    const sheen = g.createLinearGradient(x - 70, 0, x + 70, ART_H * 0.35);
    sheen.addColorStop(0, "rgba(255,255,255,0)");
    sheen.addColorStop(0.5, "rgba(255,255,255,0.32)");
    sheen.addColorStop(1, "rgba(255,255,255,0)");
    g.save();
    // Only brighten where there is armor, not the empty background.
    g.globalCompositeOperation = "lighter";
    g.fillStyle = sheen;
    g.beginPath();
    g.rect(0, 0, ART_W, ART_H);
    g.fill();
    g.restore();
    // Re-black the background the sheen touched.
    g.save();
    g.globalCompositeOperation = "destination-in";
    g.drawImage(img, 0, 0, ART_W, ART_H);
    g.restore();
    g.globalCompositeOperation = "destination-over";
    g.fillStyle = "#000";
    g.fillRect(0, 0, ART_W, ART_H);
    g.globalCompositeOperation = "source-over";
  }

}
